/**
 * SQL NULL for an RPC argument. Postgres functions accept NULL in any argument, but the generated
 * types (types.ts, regenerated by Lovable) mark arguments without a default as non-null. The
 * value sent is exactly the same; only the type is widened, at the call site, on purpose.
 */
export function rpcNull<T>(value: T | null): T {
  return value as T;
}
